    /**
     * Tests getting all DataProcessingActivitys.
     *
     * @return    Collection
     */
    public List<DataProcessingActivity> testGetAll() throws Throwable {
    LOGGER.info( "DataProcessingActivityTest:testGetAll() - Retrieving Collection of DataProcessingActivitys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all DataProcessingActivity : " );
    List<DataProcessingActivity> collection  = null;

    try {
        // call the static get method on the DataProcessingActivityService
        collection = service.getAllDataProcessingActivity();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            DataProcessingActivity currEntity  = null;
            Iterator<DataProcessingActivity> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDataProcessingActivityId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

